#!/usr/bin/env bash
# Download datasheet PDFs into each subsystem's datasheets/ folder (git-ignored).
# Run from the repository root:  bash tools/fetch-datasheets.sh
set -u
fail=0
mkdir -p subsystems/sensor/datasheets && curl -fsSL -o "subsystems/sensor/datasheets/bme688.pdf" "https://www.bosch-sensortec.com/media/boschsensortec/downloads/datasheets/bst-bme688-ds000.pdf" && echo "ok   sensor/bme688.pdf" || { echo "FAIL sensor/bme688.pdf  https://www.bosch-sensortec.com/media/boschsensortec/downloads/datasheets/bst-bme688-ds000.pdf"; fail=1; }
mkdir -p subsystems/microcontroller/datasheets && curl -fsSL -o "subsystems/microcontroller/datasheets/rp2040.pdf" "https://datasheets.raspberrypi.com/rp2040/rp2040-datasheet.pdf" && echo "ok   microcontroller/rp2040.pdf" || { echo "FAIL microcontroller/rp2040.pdf  https://datasheets.raspberrypi.com/rp2040/rp2040-datasheet.pdf"; fail=1; }
mkdir -p subsystems/microcontroller/datasheets && curl -fsSL -o "subsystems/microcontroller/datasheets/ap2112.pdf" "https://www.diodes.com/assets/Datasheets/AP2112.pdf" && echo "ok   microcontroller/ap2112.pdf" || { echo "FAIL microcontroller/ap2112.pdf  https://www.diodes.com/assets/Datasheets/AP2112.pdf"; fail=1; }
mkdir -p subsystems/power/datasheets && curl -fsSL -o "subsystems/power/datasheets/lipo-2000mah-3.7v.pdf" "https://cdn-shop.adafruit.com/datasheets/LiIon2000mAh37V.pdf" && echo "ok   power/lipo-2000mah-3.7v.pdf" || { echo "FAIL power/lipo-2000mah-3.7v.pdf  https://cdn-shop.adafruit.com/datasheets/LiIon2000mAh37V.pdf"; fail=1; }
mkdir -p subsystems/power/datasheets && curl -fsSL -o "subsystems/power/datasheets/mcp73831.pdf" "https://ww1.microchip.com/downloads/en/DeviceDoc/MCP73831-Family-Data-Sheet-DS20001984H.pdf" && echo "ok   power/mcp73831.pdf" || { echo "FAIL power/mcp73831.pdf  https://ww1.microchip.com/downloads/en/DeviceDoc/MCP73831-Family-Data-Sheet-DS20001984H.pdf"; fail=1; }
mkdir -p subsystems/power/datasheets && curl -fsSL -o "subsystems/power/datasheets/1n5818.pdf" "https://www.st.com/content/ccc/resource/technical/document/datasheet/26/db/14/60/52/47/47/5b/CD00001625.pdf/files/CD00001625.pdf/jcr:content/translations/en.CD00001625.pdf" && echo "ok   power/1n5818.pdf" || { echo "FAIL power/1n5818.pdf  https://www.st.com/content/ccc/resource/technical/document/datasheet/26/db/14/60/52/47/47/5b/CD00001625.pdf/files/CD00001625.pdf/jcr:content/translations/en.CD00001625.pdf"; fail=1; }
mkdir -p subsystems/human-interaction/datasheets && curl -fsSL -o "subsystems/human-interaction/datasheets/oled-0.91-mc091gx.pdf" "https://www.lcdwiki.com/res/MC091GX/0.91inch_IIC_OLED_Module_MC091GX_User_Manual_EN.pdf" && echo "ok   human-interaction/oled-0.91-mc091gx.pdf" || { echo "FAIL human-interaction/oled-0.91-mc091gx.pdf  https://www.lcdwiki.com/res/MC091GX/0.91inch_IIC_OLED_Module_MC091GX_User_Manual_EN.pdf"; fail=1; }
mkdir -p subsystems/human-interaction/datasheets && curl -fsSL -o "subsystems/human-interaction/datasheets/ssd1306.pdf" "https://e2e.ti.com/cfs-file/__key/communityserver-discussions-components-files/791/SSD1306-Datasheet-for-096-OLED-_2800_1_2900_.pdf" && echo "ok   human-interaction/ssd1306.pdf" || { echo "FAIL human-interaction/ssd1306.pdf  https://e2e.ti.com/cfs-file/__key/communityserver-discussions-components-files/791/SSD1306-Datasheet-for-096-OLED-_2800_1_2900_.pdf"; fail=1; }
[ "$fail" = 0 ] || echo "Some downloads failed. Open the links in the subsystem README instead."
